// List of greetings in different languages
const greetings = [
  { language: 'English',    greeting: 'Good morning! ☀️' },
  { language: 'Spanish',    greeting: '¡Buenos días! ☀️' },
  { language: 'French',     greeting: 'Bonjour! ☀️' },
  { language: 'German',     greeting: 'Guten Morgen! ☀️' },
  { language: 'Japanese',   greeting: 'おはようございます！☀️' },
  { language: 'Portuguese', greeting: 'Bom dia! ☀️' },
  { language: 'Arabic',     greeting: 'صباح الخير! ☀️' },
  { language: 'Mandarin',   greeting: '早上好！☀️' },
  { language: 'Hindi',      greeting: 'सुप्रभात! ☀️' },
  { language: 'Swahili',    greeting: 'Habari za asubuhi! ☀️' }
];

// Rotate by day-of-year so the language changes every day
const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const diff = now - start;
const oneDay = 1000 * 60 * 60 * 24;
const dayOfYear = Math.floor(diff / oneDay);

const index = dayOfYear % greetings.length;
const selected = greetings[index];

return [{ json: { language: selected.language, greeting: selected.greeting } }];
